// 1. setTimeout (렌더링 주기 무시)
function badAni() {
  // 10ms마다 실행하려 하지만 실제 프레임 생성 시점과 어긋남
  moveBox();
  setTimeout(badAni, 10);
}

// 2. requestAnimationFrame (렌더링 주기 동기화)
function goodAni() {
  moveBox();
  // 브라우저: "다음 Paint 직전에 실행시켜 줄게"
  requestAnimationFrame(goodAni);
}

requestAnimationFrame(goodAni);
